def snake_to_kebab(code):
    # Define a function to convert snake_case to kebab-case
    def convert(name):
        return '-'.join(word for word in name.split('_'))

    # Define a function to replace snake_case with kebab-case in a node
    def replace_node(node):
        if isinstance(node, ast.Name):
            return ast.Name(id=convert(node.id), ctx=ast.Load())
        elif isinstance(node, ast.Attribute):
            return ast.Attribute(
