        return None

    total_savings = 0
    for i in range(len(income)):
        if not isinstance(income[i], (int, float)) or not isinstance(expenses[i], (int, float)):
            return None
        if income[i] < 0 or expenses[i] < 0:
            return None
        savings = income[i] - expenses[i]
